async def _create_provider(client: AsyncClient, **overrides) -> dict: body = {'label': 'my-zai', 'protocol': 'openai-compatible', 'api_key': 'sk-secret-123', 'api_base': 'https://api.z.ai', **overrides}; resp = await client.post('/llm/providers', json=body); assert resp.status_code == 201, resp.text; return resp.json()
async def test_AC23_4_1_config_status_flips_when_user_configures(client: AsyncClient, cipher) -> None: 'AC-llm.4.1'; before = await client.get('/llm/config/status'); assert before.status_code == 200; assert before.json() == {'configured': False}; await _create_provider(client); after = await client.get('/llm/config/status'); assert after.json() == {'configured': True}
async def test_AC23_4_2_provider_create_encrypts_and_never_returns_key(client: AsyncClient, db: AsyncSession, cipher) -> None: 'AC-llm.4.2'; created = await _create_provider(client); assert 'api_key' not in created; assert created['has_api_key'] is True; assert created['label'] == 'my-zai'; from sqlalchemy import select; from src.llm import LlmProvider; row = (await db.execute(select(LlmProvider).where(LlmProvider.id == created['id']))).scalar_one(); assert 'sk-secret-123' not in row.api_key_ciphertext; from src.llm.base import Encrypted; assert cipher.decrypt(Encrypted(ciphertext=row.api_key_ciphertext, key_version=row.api_key_version)) == 'sk-secret-123'
