async def test_AC23_4_2_provider_list_and_delete(client: AsyncClient, cipher) -> None: 'AC-llm.4.2'; created = await _create_provider(client); listed = await client.get('/llm/providers'); assert listed.status_code == 200; ids = [p['id'] for p in listed.json()['providers']]; assert created['id'] in ids; assert all(('api_key' not in p for p in listed.json()['providers'])); deleted = await client.delete(f"/llm/providers/{created['id']}"); assert deleted.status_code == 200; assert deleted.json() == {'id': created['id'], 'deleted': True}; after = await client.get('/llm/providers'); assert created['id'] not in [p['id'] for p in after.json()['providers']]
